<script setup lang="ts">
import {ref} from 'vue';import {useWorkbench} from '../stores/workbench';import {api} from '../api/client';import DataSummary from '../components/DataSummary.vue';import StatusBadge from '../components/StatusBadge.vue';import UiIcon from '../components/UiIcon.vue';const s=useWorkbench(),tab=ref('snapshot'),preview=ref<any>(null),busy=ref(false);async function upload(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(!f)return;const form=new FormData();form.append('file',f);busy.value=true;try{preview.value=await api('/measurements/preview',{method:'POST',body:form})}catch(x:any){s.error=x.message}finally{busy.value=false;}}
</script><template><div class="page-heading"><div><div class="eyebrow">数据基础 / 跨课题协同</div><h1>数据与接口</h1><p>查看断面事实、数据质量与接口契约，所有模型修改都可追溯到这里。</p></div><span class="page-icon"><UiIcon name="data" :size="30"/></span></div><el-tabs v-model="tab" class="page-tabs"><el-tab-pane label="断面与数据质量" name="snapshot"><div class="two-columns align-start"><section class="panel panel-pad snapshot-side"><div class="section-heading"><h2>断面库</h2><span class="count-pill">{{s.snapshots.length}} 个文件</span></div><button v-for="snap in s.snapshots" :key="snap.id" class="snapshot-entry" :class="{selected:s.snapshotId===snap.id}" @click="s.selectSnapshot(snap.id)"><UiIcon name="file"/><span><strong>{{snap.time||snap.start||snap.id}}</strong><small>{{snap.filename||snap.id}}</small></span><UiIcon name="check" v-if="s.snapshotId===snap.id"/></button><div v-if="s.summary?.single_snapshot" class="notice amber"><UiIcon name="info"/><div><strong>单断面演示模式</strong><p>当前断面按 15 分钟间隔复制为 16 个时段，用于展示 4 小时建模窗口。</p></div></div><p class="footnote">名称与编号登记表尚为空；当前使用 B / L / G 稳定编号，等待课题 2 提供设备名称映射。</p></section><section class="panel panel-pad"><DataSummary/></section></div></el-tab-pane><el-tab-pane label="外部接口" name="integrations"><div class="integration-grid"><section v-for="i in s.integrations" :key="i.id" class="panel panel-pad"><div class="section-heading"><h2>{{i.name}}</h2><StatusBadge :feature="i.feature_id||i.id" :name="i.name"/></div><p class="muted">{{i.description}}</p><div class="key-value"><span>当前模式</span><code>{{i.mode||i.status}}</code><span>服务地址</span><code>{{i.endpoint||'未配置'}}</code></div><details><summary>请求与响应契约</summary><h4>请求</h4><pre class="json-block">{{JSON.stringify(i.request||{},null,2)}}</pre><h4>响应</h4><pre class="json-block">{{JSON.stringify(i.response||{},null,2)}}</pre></details></section></div></el-tab-pane><el-tab-pane label="课题 2 测点预览" name="measurements"><section class="panel panel-pad"><div class="section-heading"><h2>测点数据文件</h2><StatusBadge name="课题 2 测点数据"/></div><div class="upload-zone"><UiIcon name="data" :size="32"/><h3>导入 XLSX / CSV，预览表格</h3><p>仅预览原始列与记录，测点 → 节点转换待开发。</p><label class="upload-button"><input type="file" accept=".csv,.xlsx" @change="upload" :disabled="busy"/>{{busy?'正在读取…':'选择测点文件'}}</label></div><template v-if="preview"><h3>{{preview.filename}} · {{preview.total}} 行</h3><el-table :data="preview.rows" max-height="450" border><el-table-column v-for="c in preview.columns" :key="c" :prop="c" :label="c" min-width="140"/></el-table></template></section></el-tab-pane></el-tabs></template>